Now let me write the sweep. The segment vs inflated AABB:

```js
function segmentHitsInflated(x0, y0, x1, y1, brick, r) {
  const left = brick.x - r;
  const right = brick.x + brick.w + r;
  const top = brick.y - r;
  const bottom = brick.y + brick.h + r;
  const dx = x1 - x0;
  const dy = y1 - y0;
  let t0 = 0;
  let t1 = 1;
  const p = [-dx, dx, -dy, dy];
  const q = [x0 - left, right - x0, y0 - top, bottom - y0];
  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return null; // parallel and outside
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return null;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return null;
        if (t < t1) t1 = t;
      }
    }
  }
  // t0 = entry, t1 = exit
  return { t0, t1, left, right, top, bottom };
}
```

