```js
// Chooses the face of `brick` the ball hit, from their current overlap, and
// returns a small descriptor { flipX, flipY, x, y } describing the bounce:
// the velocity components to force away from the brick and the position to
// push the ball back to (so it stops overlapping next frame).
function faceFromOverlap(ball, brick) {
  const fromLeft = ball.x + ball.r - brick.x;
  const fromRight = brick.x + brick.w - (ball.x - ball.r);
  const fromTop = ball.y + ball.r - brick.y;
  const fromBottom = brick.y + brick.h - (ball.y - ball.r);
  const overlapX = Math.min(fromLeft, fromRight);
  const overlapY = Math.min(fromTop, fromBottom);

  if (overlapX < overlapY) {
    // side hit
    const fromLeftSmaller = fromLeft < fromRight;
    return {
      flipX: true,
      flipY: false,
      x: fromLeftSmaller ? brick.x - ball.r : brick.x + brick.w + ball.r,
      y: null,
    };
  }
  if (overlapY < overlapX) {
    const fromTopSmaller = fromTop < fromBottom;
    return {
      flipX: false,
      flipY: true,
      x: null,
      y: fromTopSmaller ? brick.y - ball.r : brick.y + brick.h + ball.r,
    };
  }
  // corner: equal penetrations — diagonal hit, flip both
  const fromLeftSmaller = fromLeft < fromRight;
  const fromTopSmaller = fromTop < fromBottom;
  return {
    flipX: true,
    flipY: true,
    x: fromLeftSmaller ? brick.x - ball.r : brick.x + brick.w + ball.r,
    y: fromTopSmaller ? brick.y - ball.r : brick.y + brick.h + ball.r,
  };
}
```

