function faceFromSweep(x0, y0, x1, y1, brick, r) {
  // Liang-Barsky: where does the segment enter the brick inflated by r?
  const left = brick.x - r, right = brick.x + brick.w + r;
  const top = brick.y - r, bottom = brick.y + brick.h + r;
  const dx = x1 - x0, dy = y1 - y0;
  let t0 = 0, t1 = 1;
  const p = [-dx, dx, -dy, dy];
  const q = [x0 - left, right - x0, y0 - top, bottom - y0];
  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return null;
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return null;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return null;
        if (t < t1) t1 = t;
      }
    }
  }
  if (t1 <= t0) return null; // tangent / degenerate — not a real crossing

  // Which face does the segment enter through?
  const entryX = x0 + dx * t0;
  const entryY = y0 + dy * t0;
  const eps = 1e-6;
  if (Math.abs(entryX - left) <= eps) {
    return { flipX: true, flipY: false, x: left - r, y: null };
  }
  if (Math.abs(entryX - right) <= eps) {
    return { flipX: true, flipY: false, x: right + r, y: null };
  }
  if (Math.abs(entryY - top) <= eps) {
    return { flipX: false, flipY: true, x: null, y: top - r };
  }
  return { flipX: false, flipY: true, x: null, y: bottom + r };
}
