```js
export function brickHit(ball, bricks, prevX = ball.x, prevY = ball.y) {
  const destroyed = [];
  let bounceApplied = false;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    let hit = null;
    if (collides(ball, brick)) {
      hit = faceFromOverlap(ball, brick);
    } else {
      hit = faceFromSweep(prevX, prevY, ball.x, ball.y, brick, ball.r);
    }
    if (!hit) continue;

    brick.alive = false;
    destroyed.push(brick);

    // Bounce exactly once, whatever the number of overlapping bricks.
    if (!bounceApplied) {
      bounceApplied = true;
      bounce(ball, hit);
    }
  }
  return destroyed;
}
```

