export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // ... walls, ceiling, paddle unchanged ...

  // Bricks: destroy what the ball touched and bounce it (exactly once).
  const destroyed = brickHit(ball, state.bricks, prevX, prevY);
  for (const brick of destroyed) {
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) return true;
  return false;
}
```

