// Liang-Barsky clip: returns the entry/exit parameters of the segment
// (x0,y0)→(x1,y1) against the axis-aligned box, or null when it misses.
// The box is the brick inflated by the ball radius: a segment hitting it is
// exactly the swept (tunnelling) test of the ball against the brick.
function sweepBox(x0, y0, x1, y1, left, top, right, bottom) {
  const dx = x1 - x0;
  const dy = y1 - y0;
  const p = [-dx, dx, -dy, dy];
  const q = [x0 - left, right - x0, y0 - top, bottom - y0];
  let t0 = 0;
  let t1 = 1;
  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return null; // parallel to the slab, outside
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return null;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return null;
        if (t < t1) t1 = t;
      }
    }
  }
  // A zero-length intersection is a tangent point, not a crossing.
  if (t1 <= t0) return null;
  return { t0, t1, left, top, right, bottom };
}
```

