// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — that decision is made by `faceFromOverlap` below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick bounce (ISSUES.md #1) --------------------------------------------

// Two penetrations closer than this count as a tie (diagonal/corner hit).
const CORNER_EPS = 1e-6;

// Applies a resolved bounce: forces each touched velocity component to point
// AWAY from the brick (|vx|/|vy| × the ±1 sign) and pushes the ball out of the
// brick so it cannot re-overlap next frame. Forcing the sign — instead of
// flipping it — keeps a ball that is already leaving from being sent back in
// (sticky bounce).
function bounce(ball, hit) {
  if (hit.vx !== 0) ball.vx = Math.abs(ball.vx) * hit.vx;
  if (hit.vy !== 0) ball.vy = Math.abs(ball.vy) * hit.vy;
  if (hit.x !== null) ball.x = hit.x;
  if (hit.y !== null) ball.y = hit.y;
}

// Picks the face of `brick` the ball overlaps. The axis with the SMALLER
// penetration is the face that was hit: flip `vy` on a top/bottom hit, `vx` on
// a side hit, both when the penetrations tie (diagonal hit through a corner).
function faceFromOverlap(ball, brick) {
  const fromLeft = ball.x + ball.r - brick.x;
  const fromRight = brick.x + brick.w - (ball.x - ball.r);
  const fromTop = ball.y + ball.r - brick.y;
  const fromBottom = brick.y + brick.h - (ball.y - ball.r);
  const overlapX = Math.min(fromLeft, fromRight);
  const overlapY = Math.min(fromTop, fromBottom);

  if (overlapX < overlapY - CORNER_EPS) {
    // Side hit: entered through the left face, bounce back left and push the
    // ball out of that face; mirror for the right face.
    return fromLeft < fromRight
      ? { vx: -1, vy: 0, x: brick.x - ball.r, y: null }
      : { vx: 1, vy: 0, x: brick.x + brick.w + ball.r, y: null };
  }
  if (overlapY < overlapX - CORNER_EPS) {
    // Top/bottom hit.
    return fromTop < fromBottom
      ? { vx: 0, vy: -1, x: null, y: brick.y - ball.r }
      : { vx: 0, vy: 1, x: null, y: brick.y + brick.h + ball.r };
  }
  // Corner: equal penetrations mean a diagonal hit — bounce off both axes.
  return {
    vx: fromLeft < fromRight ? -1 : 1,
    vy: fromTop < fromBottom ? -1 : 1,
    x: fromLeft < fromRight ? brick.x - ball.r : brick.x + brick.w + ball.r,
    y: fromTop < fromBottom ? brick.y - ball.r : brick.y + brick.h + ball.r,
  };
}

// Liang-Barsky clip of the segment (x0,y0)→(x1,y1) against an axis-aligned
// box. Returns the entry/exit parameters, or null when the segment misses.
// Used with the brick inflated by the ball radius: the segment crossing that
// box is exactly the swept test of the ball against the brick, which catches
// tunnelling (a stuttered frame can move the ball a whole row in one step).
function sweepBox(x0, y0, x1, y1, left, top, right, bottom) {
  const dx = x1 - x0;
  const dy = y1 - y0;
  const p = [-dx, dx, -dy, dy];
  const q = [x0 - left, right - x0, y0 - top, bottom - y0];
  let t0 = 0;
  let t1 = 1;
  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return null; // parallel to the slab, outside
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return null;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return null;
        if (t < t1) t1 = t;
      }
    }
  }
  // A zero-length intersection is a tangent point, not a crossing.
  if (t1 <= t0) return null;
  return { t0, t1, left, top, right, bottom };
}

// Bounce face when the ball never overlapped the brick but its path crossed it
// between two steps (tunnelling): the face it ENTERED through.
function faceFromSweep(ball, brick, x0, y0) {
  const left = brick.x - ball.r;
  const right = brick.x + brick.w + ball.r;
  const top = brick.y - ball.r;
  const bottom = brick.y + brick.h + ball.r;
  const sweep = sweepBox(x0, y0, ball.x, ball.y, left, top, right, bottom);
  if (!sweep) return null;
  const entryX = x0 + (ball.x - x0) * sweep.t0;
  const entryY = y0 + (ball.y - y0) * sweep.t0;
  const eps = 1e-6;
  if (Math.abs(entryX - left) <= eps) return { vx: -1, vy: 0, x: left, y: null };
  if (Math.abs(entryX - right) <= eps) return { vx: 1, vy: 0, x: right, y: null };
  if (Math.abs(entryY - top) <= eps) return { vx: 0, vy: -1, x: null, y: top };
  return { vx: 0, vy: 1, x: null, y: bottom };
}

// Resolves ball↔brick collisions for one step and returns the destroyed
// bricks. Every touched brick is destroyed, but the bounce is applied EXACTLY
// ONCE, from the first brick hit: the 8 px grid gap is smaller than the ball,
// so a seam overlaps two bricks in the same pass, and two flips would cancel
// out (the ball would plow straight through). `prevX`/`prevY` are the ball's
// position before the move; without them the sweep cannot detect tunnelling.
export function brickHit(ball, bricks, prevX = ball.x, prevY = ball.y) {
  const destroyed = [];
  let bounced = false;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    const hit = collides(ball, brick)
      ? faceFromOverlap(ball, brick)
      : faceFromSweep(ball, brick, prevX, prevY);
    if (!hit) continue;

    brick.alive = false;
    destroyed.push(brick);

    if (!bounced) {
      bounced = true;
      bounce(ball, hit);
    }
  }
  return destroyed;
}

