test('brickHit: head-on top hit flips vy up, pushes the ball out, destroys the brick', () => {
  const brick = { x: 100, y: 100, w: 60, h: 20, alive: true };
  const ball = { x: 130, y: 105, r: 7, vx: 0, vy: 200 }; // 5px into the top face
  const destroyed = brickHit(ball, [brick], 130, 90);
  assert.equal(destroyed.length, 1);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, -200, 'top hit bounces the ball back up');
  assert.equal(ball.y + ball.r, brick.y, 'ball pushed out above the brick');
});

test('brickHit: head-on bottom hit flips vy down (ball climbing into the bricks)', () => {
  const brick = { x: 100, y: 100, w: 60, h: 20, alive: true };
  const ball = { x: 130, y: 115, r: 7, vx: 0, vy: -200 }; // 5px into the bottom face
  const destroyed = brickHit(ball, [brick], 130, 140);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vy, 200, 'bottom hit bounces the ball back down');
  assert.equal(ball.y - ball.r, brick.y + brick.h, 'ball pushed out below the brick');
});

test('brickHit: side hit flips vx and pushes the ball out sideways', () => {
  const brick = { x: 200, y: 100, w: 60, h: 20, alive: true };
  const ball = { x: 205, y: 110, r: 7, vx: 200, vy: 0 }; // 5px in from the left face
  const destroyed = brickHit(ball, [brick], 150, 110);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vx, -200, 'left face hit bounces the ball back left');
  assert.equal(ball.x + ball.r, brick.x, 'ball pushed out to the left of the brick');
});

test('brickHit: corner hit (tied penetrations) bounces off both axes', () => {
  const brick = { x: 200, y: 100, w: 60, h: 20, alive: true };
  const ball = { x: 202, y: 102, r: 7, vx: 200, vy: 100 }; // diagonal into the corner
  const destroyed = brickHit(ball, [brick], 160, 90);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vx, -200);
  assert.equal(ball.vy, -100);
  assert.equal(ball.x + ball.r, brick.x);
  assert.equal(ball.y + ball.r, brick.y);
});

test('brickHit: seam destroys both neighbours but bounces exactly once', () => {
  // The 8px gap is smaller than the ball, so a seam overlaps two bricks.
  const leftBrick = { x: 200, y: 100, w: 60, h: 20, alive: true };
  const rightBrick = { x: 268, y: 100, w: 60, h: 20, alive: true };
  const ball = { x: 263, y: 110, r: 7, vx: -100, vy: 0 }; // centred in the seam
  const destroyed = brickHit(ball, [leftBrick, rightBrick], 300, 110);
  assert.equal(destroyed.length, 2, 'both seam bricks are destroyed');
  assert.equal(leftBrick.alive, false);
  assert.equal(rightBrick.alive, false);
  // A single flip (not two, which would cancel out and let the ball through).
  assert.equal(ball.vx, 100, 'ball bounced off the seam once');
  assert.equal(ball.x - ball.r, leftBrick.x + leftBrick.w, 'ball pushed into the gap');
});

test('brickHit: sweep catches a ball that jumps over a brick (tunnelling)', () => {
  // Level 6 moves 35.5px/step against a 34px brick crossing — the ball lands
  // on the far side without ever overlapping. The sweep must still hit it.
  const brick = { x: 100, y: 100, w: 60, h: 20, alive: true };
  const ball = { x: 130, y: 140, r: 7, vx: 0, vy: 500 }; // ended below the brick
  const destroyed = brickHit(ball, [brick], 130, 80); // was above it last step
  assert.equal(destroyed.length, 1);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, -500, 'bounced back up off the top face it crossed');
  assert.equal(ball.y, brick.y - ball.r, 'pushed back above the brick');
});

test('brickHit: no contact leaves the bricks alone', () => {
  const brick = { x: 100, y: 100, w: 60, h: 20, alive: true };
  const ball = { x: 500, y: 300, r: 7, vx: 0, vy: 0 };
  const destroyed = brickHit(ball, [brick]);
  assert.equal(destroyed.length, 0);
  assert.equal(brick.alive, true);
});

test('step: ball bounces off a brick instead of passing through, scores it', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 300;
  brick.y = 100;
  brick.w = 40;
  brick.h = 20;
  for (const b of state.bricks) {
    if (b !== brick) b.alive = false;
  }
  state.ball = { x: 320, y: 130, r: 7, vx: 0, vy: -300 }; // climbing into the brick
  step(state, 1 / 60); // moves the ball up by 5px → 2px into the bottom face
  assert.equal(brick.alive, false, 'brick destroyed by the physics step');
  assert.equal(state.ball.vy, 300, 'ball bounced down instead of passing through');
  assert.ok(state.score > 0, 'destroying a brick scores points');
  assert.equal(state.combo, 1);
});

